                            t.HasCheckConstraint("ck_vocabulary_sense_translations_usage_note", "usage_note IS NULL OR usage_note ~ '[^[:space:]]'");

                            t.HasCheckConstraint("ck_vocabulary_sense_translations_version", "version > 0");
